<?php namespace Hongda\Theme; get_header();while(have_posts()):the_post(); ?><section class="page-intro"><div class="wrap"><span class="eyebrow">HONGDA MACHINERY</span><h1><?php the_title(); ?></h1></div></section><section class="section wrap story-split"><aside><?php $parent=wp_get_post_parent_id(get_the_ID());$children=get_pages(['child_of'=>$parent?:get_the_ID(),'parent'=>$parent?:get_the_ID(),'sort_column'=>'menu_order,post_title']);foreach($children as $child): ?><a class="side-link" href="<?php echo esc_url(get_permalink($child)); ?>"><?php echo esc_html($child->post_title); ?> ↗</a><?php endforeach; ?></aside><div class="prose"><?php the_content(); if(wp_get_post_parent_id(get_the_ID())===(int)get_theme_mod('contact_page')): ?><a class="button" href="<?php echo esc_url(enquiry()); ?>">Discuss your requirements ↗</a><?php endif; ?></div></section><?php endwhile;get_footer(); ?>
